export async function withTransaction(pool, fn) {
  const client = await pool.connect();
  try { await client.query('BEGIN'); const out = await fn(client); await client.query('COMMIT'); return out; }
  catch (e) { await client.query('ROLLBACK'); throw e; }
  finally { client.release(); }
}

export const placeOrder = (pool, req) => withTransaction(pool, async (c) => {
  const { rows } = await c.query('INSERT INTO orders (customer_id) VALUES ($1) RETURNING id', [req.customerId]);
  await reserveStock(c, rows[0].id);      // same client, same transaction
  return rows[0].id;
});
